Selector(\'.fisica-home-carousel__track\');\\n  const slides = Array.from(root.querySelectorAll(\'.fisica-home-carousel__slide\'));\\n  const next = root.querySelector(\'[data-carousel-next]\');\\n  const prev = root.querySelector(\'[data-carousel-prev]\');\\n  const dotsWrap = root.querySelector(\'[data-carousel-dots]\');\\n\\n  if (!track || !slides.length || !next || !prev || !dotsWrap) {\\n    return;\\n  }\\n\\n  let index = 0;\\n  let timer = null;\\n\\n  const dots = slides.map((_, i) => {\\n    const dot = document.createElement(\'button\');\\n    dot.type = \'button\';\\n    dot.className = \'fisica-home-carousel__dot\';\\n    dot.setAttribute(\'aria-label\', `Ir para slide ${i + 1}`);\\n    dot.addEventListener(\'click\', () => {\\n      goTo(i);\\n      restart();\\n    });\\n    dotsWrap.appendChild(dot);\\n    return dot;\\n  });\\n\\n  function render() {\\n    track.style.transform = `translateX(-${index * 100}%)`;\\n    dots.forEach((dot, dotIndex) => {\\n      dot.classList.toggle(\'is-active\', dotIndex === index);\\n    });\\n  }\\n\\n  function goTo(nextIndex) {\\n    index = (nextIndex + slides.length) % slides.length;\\n    render();\\n  }\\n\\n  function restart() {\\n    window.clearInterval(timer);\\n    timer = window.setInterval(() => goTo(index + 1), 5500);\\n  }\\n\\n  next.addEventListener(\'click\', () => {\\n    goTo(index + 1);\\n    restart();\\n  });\\n\\n  prev.addEventListener(\'click\', () => {\\n    goTo(index - 1);\\n    restart();\\n  });\\n\\n  render();\\n  restart();\\n})();\\n<\\/script>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"homeevents1\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\"},\"elements\":[{\"id\":\"eventhtml1\",\"elType\":\"widget\",\"settings\":{\"html\":\"<section class=\\\"fisica-home-section\\\">\\n  <div class=\\\"fisica-home-section__head\\\">\\n    <div>\\n      <span class=\\\"fisica-home-section__eyebrow\\\">Eventos e Destaques<\\/span>\\n      <h2>Acontece no instituto<\\/h2>\\n      <!--<p>Um bloco mais organizado para divulgar atividades, imagens e acontecimentos relevantes da comunidade acad\\u00eamica.<\\/p>-->\\n    <\\/div>\\n  <\\/div>\\n\\n  <div class=\\\"fisica-events-grid\\\">\\n    <a class=\\\"fisica-events-card\\\" href=\\\"http:\\/\\/localhost\\/fisica\\/wp-content\\/uploads\\/2025\\/09\\/WhatsApp-Image-2025-08-25-at-15.23.48.jpg\\\" style=\\\"background-image:url(\'http:\\/\\/localhost\\/fisica\\/wp-content\\/uploads\\/2025\\/09\\/WhatsApp-Image-2025-08-25-at-15.23.48.jpg\');\\\">\\n      <div class=\\\"fisica-events-card__content\\\">\\n        <span class=\\\"fisica-events-card__tag\\\">Galeria<\\/span>\\n        <h3>Registro visual das atividades mais recentes<\\/h3>\\n        <p>Imagens em destaque para comunicar melhor a vida acad\\u00eamica, os projetos e os eventos do instituto.<\\/p>\\n      <\\/div>\\n    <\\/a>\\n    <a class=\\\"fisica-events-card\\\" href=\\\"http:\\/\\/localhost\\/fisica\\/wp-content\\/uploads\\/2025\\/09\\/WhatsApp-Image-2025-08-25-at-15.22.50.jpg\\\" style=\\\"background-image:url(\'http:\\/\\/localhost\\/fisica\\/wp-content\\/uploads\\/2025\\/09\\/WhatsApp-Image-2025-08-25-at-15.22.50.jpg\');\\\">\\n      <div class=\\\"fisica-events-card__content\\\">\\n        <span class=\\\"fisica-events-card__tag\\\">Comunidade<\\/span>\\n        <h3>Projetos, encontros e circula\\u00e7\\u00e3o de conhecimento<\\/h3>\\n        <p>Uma apresenta\\u00e7\\u00e3o visual mais forte para valorizar atividades de ensino, pesquisa, extens\\u00e3o e integra\\u00e7\\u00e3o institucional.<\\/p>\\n      <\\/div>\\n    <\\/a>\\n        <a class=\\\"fisica-events-card\\\" href=\\\"http:\\/\\/localhost\\/fisica\\/index.php\\/rpc-2026-na-uerj-abre-inscricoes-e-submissao-de-resumos\\/\\\" style=\\\"background-image:url(\'http:\\/\\/localhost\\/fisica\\/wp-content\\/uploads\\/2026\\/05\\/Captura-de-tela-2026-05-14-152836.png\');\\\">\\n      <div class=\\\"fisica-events-card__content\\\">\\n        <span class=\\\"fisica-events-card__tag\\\">Evento internacional<\\/span>\\n        <h3>RPC 2026 na UERJ abre inscri\\u00e7\\u00f5es e submiss\\u00e3o de resumos<\\/h3>\\n        <p>UERJ sediar\\u00e1 pela primeira vez no Brasil e na Am\\u00e9rica do Sul a International Conference on Resistive Plate Chambers and Related Detectors (RPC 2026), reunindo pesquisadores e especialistas de diversos pa\\u00edses.<\\/p>\\n      <\\/div>\\n    <\\/a>\\n  <\\/div>\\n<\\/section>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"labsanchor1\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\"},\"elements\":[{\"id\":\"labshtml1\",\"elType\":\"widget\",\"settings\":{\"html\":\"<div id=\\\"laboratorios\\\"><\\/div>\"},\"elements\":[],\"widgetType\":\"html\"},{\"id\":\"labsshort1\",\"elType\":\"widget\",\"settings\":{\"shortcode\":\"[icones_servicos_uerj]\"},\"elements\":[],\"widgetType\":\"shortcode\"}],\"isInner\":false},{\"id\":\"programanchor1\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\"},\"elements\":[{\"id\":\"programhtml1\",\"elType\":\"widget\",\"settings\":{\"html\":\"<div id=\\\"programas\\\"><\\/div>\"},\"elements\":[],\"widgetType\":\"html\"},{\"id\":\"programshort1\",\"elType\":\"widget\",\"settings\":{\"shortcode\":\"[quadrados_servicos_link]\"},\"elements\":[],\"widgetType\":\"shortcode\"}],\"isInner\":false}]'),(6608,1106,'_elementor_edit_mode','builder'),(6614,1107,'_wp_attached_file','2026/05/GEO_3073-2.jpg'),(6615,1107,'_wp_attachment_metadata','a:6:{s:5:\"width\";i:7808;s:6:\"height\";i:5205;s:4:\"file\";s:22:\"2026/05/GEO_3073-2.jpg\";s:8:\"filesize\";i:25717737;s:5:\"sizes\";a:0:{}s:10:\"image_meta\";a:12:{s:8:\"aperture\";s:3:\"6.3\";s:6:\"credit\";s:15:\"GEORGE MAGARAIA\";s:6:\"camera\";s:10:\"NIKON D850\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:10:\"1749670553\";s:9:\"copyright\";s:15:\