\'[data-docentes-search]\');\\n      const feedback = app.querySelector(\'[data-docentes-feedback]\');\\n\\n      const activate = (index) => {\\n        tabs.forEach((tab, tabIndex) => {\\n          const active = tabIndex === index;\\n          tab.classList.toggle(\'is-active\', active);\\n          tab.setAttribute(\'aria-selected\', active ? \'true\' : \'false\');\\n        });\\n\\n        panels.forEach((panel, panelIndex) => {\\n          const active = panelIndex === index;\\n          panel.classList.toggle(\'is-active\', active);\\n          panel.hidden = !active;\\n        });\\n\\n        filterRows();\\n      };\\n\\n      const filterRows = () => {\\n        const activePanel = app.querySelector(\'.fisica-docentes-panel.is-active\');\\n        if (!activePanel) {\\n          return;\\n        }\\n\\n        const term = (search?.value || \'\').trim().toLowerCase();\\n        const rows = Array.from(activePanel.querySelectorAll(\'.fisica-docentes-row\'));\\n        let visible = 0;\\n\\n        rows.forEach((row) => {\\n          const haystack = row.dataset.search || \'\';\\n          const match = term === \'\' || haystack.includes(term);\\n          row.hidden = !match;\\n          if (match) {\\n            visible += 1;\\n          }\\n        });\\n\\n        const empty = activePanel.querySelector(\'.fisica-docentes-empty\');\\n        if (empty) {\\n          empty.hidden = visible !== 0;\\n        }\\n\\n        if (feedback) {\\n          if (term === \'\') {\\n            feedback.textContent = \'Consulte a rela\\u00e7\\u00e3o completa de docentes por \\u00e1rea.\';\\n          } else {\\n            feedback.textContent = visible + \' docente(s) encontrado(s) na \\u00e1rea selecionada.\';\\n          }\\n        }\\n      };\\n\\n      tabs.forEach((tab) => {\\n        tab.addEventListener(\'click\', () => activate(Number(tab.dataset.docentesTab || 0)));\\n      });\\n\\n      search?.addEventListener(\'input\', filterRows);\\n      activate(0);\\n    })();\\n  <\\/script>\\n<\\/section>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false}]'),(6800,1138,'_elementor_edit_mode','builder'),(6801,1138,'_elementor_template_type','wp-page'),(6802,1138,'_elementor_version','3.32.1'),(6803,1138,'_wp_page_template','elementor_header_footer'),(6804,1138,'_elementor_data','[{\"id\":\"fisicadocenteshtmlv2\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"fisicadocenteshtmlwidgetv2\",\"elType\":\"widget\",\"settings\":{\"html\":\"<section class=\\\"fisica-docentes-page\\\" data-docentes-app>\\n  <style>\\n    .fisica-docentes-page {\\n      --fisica-doc-bg: #f5f8fc;\\n      --fisica-doc-card: #ffffff;\\n      --fisica-doc-card-soft: #edf5ff;\\n      --fisica-doc-text: #16324f;\\n      --fisica-doc-text-soft: #557089;\\n      --fisica-doc-primary: #0f4c81;\\n      --fisica-doc-primary-strong: #0b2f4a;\\n      --fisica-doc-accent: #59a8ff;\\n      --fisica-doc-border: rgba(15, 76, 129, 0.14);\\n      --fisica-doc-shadow: 0 24px 56px rgba(11, 47, 74, 0.12);\\n      --fisica-doc-shadow-soft: 0 14px 30px rgba(11, 47, 74, 0.08);\\n      max-width: 1400px;\\n      margin: 0 auto;\\n      padding: 28px 18px 70px;\\n      color: var(--fisica-doc-text);\\n      font-family: \\\"Segoe UI\\\", \\\"Helvetica Neue\\\", Arial, sans-serif;\\n    }\\n    .fisica-docentes-page * {\\n      box-sizing: border-box;\\n    }\\n    .fisica-docentes-hero {\\n      position: relative;\\n      overflow: hidden;\\n      margin-bottom: 26px;\\n      padding: clamp(28px, 5vw, 42px);\\n      border-radius: 30px;\\n      background:\\n        radial-gradient(circle at top right, rgba(89, 168, 255, 0.32), transparent 28%),\\n        linear-gradient(135deg, #0b2f4a 0%, #0f4c81 58%, #1f6fb4 100%);\\n      box-shadow: 0 26px 58px rgba(11, 47, 74, 0.22);\\n 