       return;\\n        }\\n\\n        const term = (search?.value || \'\').trim().toLowerCase();\\n        const rows = Array.from(activePanel.querySelectorAll(\'.fisica-docentes-row\'));\\n        let visible = 0;\\n\\n        rows.forEach((row) => {\\n          const haystack = row.dataset.search || \'\';\\n          const match = term === \'\' || haystack.includes(term);\\n          row.hidden = !match;\\n          if (match) {\\n            visible += 1;\\n          }\\n        });\\n\\n        const empty = activePanel.querySelector(\'.fisica-docentes-empty\');\\n        if (empty) {\\n          empty.hidden = visible !== 0;\\n        }\\n\\n        if (feedback) {\\n          if (term === \'\') {\\n            feedback.textContent = \'Consulte a rela\\u00e7\\u00e3o completa de docentes por \\u00e1rea.\';\\n          } else {\\n            feedback.textContent = visible + \' docente(s) encontrado(s) na \\u00e1rea selecionada.\';\\n          }\\n        }\\n      };\\n\\n      tabs.forEach((tab) => {\\n        tab.addEventListener(\'click\', () => activate(Number(tab.dataset.docentesTab || 0)));\\n      });\\n\\n      search?.addEventListener(\'input\', filterRows);\\n      activate(0);\\n    })();\\n  <\\/script>\\n<\\/section>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false}]'),(7284,1186,'_elementor_page_assets','a:1:{s:7:\"scripts\";a:1:{i:0;s:18:\"elementor-frontend\";}}'),(7285,1186,'_elementor_css','a:6:{s:4:\"time\";i:1779386308;s:5:\"fonts\";a:0:{}s:5:\"icons\";a:0:{}s:20:\"dynamic_elements_ids\";a:0:{}s:6:\"status\";s:4:\"file\";i:0;s:0:\"\";}'),(7286,1186,'_elementor_element_cache','{\"timeout\":1779461908,\"value\":{\"content\":\"<div class=\"elementor-element elementor-element-fisicadocenteshtmlv2 e-con-full e-flex e-con e-parent\" data-id=\"fisicadocenteshtmlv2\" data-element_type=\"container\">ntttt<div class=\"elementor-element elementor-element-fisicadocenteshtmlwidgetv2 elementor-widget elementor-widget-html\" data-id=\"fisicad