section>n  </div>nn  <script>n    (() => {n      const app = document.querySelector(\'[data-docentes-app]\');n      if (!app || app.dataset.ready === \'true\') {n        return;n      }n      app.dataset.ready = \'true\';nn      const tabs = Array.from(app.querySelectorAll(\'[data-docentes-tab]\'));n      const panels = Array.from(app.querySelectorAll(\'.fisica-docentes-panel\'));n      const search = app.querySelector(\'[data-docentes-search]\');n      const feedback = app.querySelector(\'[data-docentes-feedback]\');nn      const activate = (index) => {n        tabs.forEach((tab, tabIndex) => {n          const active = tabIndex === index;n          tab.classList.toggle(\'is-active\', active);n          tab.setAttribute(\'aria-selected\', active ? \'true\' : \'false\');n        });nn        panels.forEach((panel, panelIndex) => {n          const active = panelIndex === index;n          panel.classList.toggle(\'is-active\', active);n          panel.hidden = !active;n        });nn        filterRows();n      };nn      const filterRows = () => {n        const activePanel = app.querySelector(\'.fisica-docentes-panel.is-active\');n        if (!activePanel) {n          return;n        }nn        const term = (search?.value || \'\').trim().toLowerCase();n        const rows = Array.from(activePanel.querySelectorAll(\'.fisica-docentes-row\'));n        let visible = 0;nn        rows.forEach((row) => {n          const haystack = row.dataset.search || \'\';n          const match = term === \'\' || haystack.includes(term);n          row.hidden = !match;n          if (match) {n            visible += 1;n          }n        });nn        const empty = activePanel.querySelector(\'.fisica-docentes-empty\');n        if (empty) {n          empty.hidden = visible !== 0;n        }nn        if (feedback) {n          if (term === \'\') {n            feedback.textContent = \'Consulte a relau00e7u00e3o completa de docentes por u00e1rea.\';n          } else {n            feedback.textContent = visible + \' docente(s) encontrado(s) na u00e1rea selecionada.\';n          }n        }n      };nn      tabs.forEach((tab) => {n        tab.addEventListener(\'click\', () => activate(Number(tab.dataset.docentesTab || 0)));n      });nn      search?.addEventListener(\'input\', filterRows);n      activate(0);n    })();n  </script>n</section>tttt</div>ntttt</div>ntt\",\"scripts\":[],\"styles\":[]}}'),(7287,295,'_elementor_css','a:6:{s:4:\"time\";i:1779386456;s:5:\"fonts\";a:0:{}s:5:\"icons\";a:0:{}s:20:\"dynamic_elements_ids\";a:0:{}s:6:\"status\";s:4:\"file\";i:0;s:0:\"\";}'),(7288,295,'_elementor_element_cache','{\"timeout\":1779462056,\"value\":{\"content\":\"<div class=\\\"elementor-element elementor-element-fisicadocenteshtmlv2 e-con-full e-flex e-con e-parent\\\" data-id=\\\"fisicadocenteshtmlv2\\\" data-element_type=\\\"container\\\">\\n\\t\\t\\t\\t<div class=\\\"elementor-element elementor-element-fisicadocenteshtmlwidgetv2 elementor-widget elementor-widget-html\\\" data-id=\\\"fisicadocenteshtmlwidgetv2\\\" data-element_type=\\\"widget\\\" data-widget_type=\\\"html.default\\\">\\n\\t\\t\\t\\t\\t<section class=\\\"fisica-docentes-page\\\" data-docentes-app>\\n  <style>\\n    .fisica-docentes-page {\\n      --fisica-doc-bg: #f5f8fc;\\n      --fisica-doc-card: #ffffff;\\n      --fisica-doc-card-soft: #edf5ff;\\n      --fisica-doc-text: #16324f;\\n      --fisica-doc-text-soft: #557089;\\n      --fisica-doc-primary: #0f4c81;\\n      --fisica-doc-primary-strong: #0b2f4a;\\n      --fisica-doc-accent: #59a8ff;\\n      --fisica-doc-border: rgba(15, 76, 129, 0.14);\\n      --fisica-doc-shadow: 0 24px 56px rgba(11, 47, 74, 0.12);\\n      --fisica-doc-shadow-soft: 0 14px 30px rgba(11, 47, 74, 0.08);\\n      max-width: 1400px;\\n      margin: 0 auto;\\n      padding: 28px 18px 70px;\\n      color: var(--fisica-doc-text);\\n      font-family: \\\"Segoe UI\\\", \\\"Helvetica Neue\\\", Arial, sans-serif;\\n    }\\n    .fisica-docentes-page * {\\n      box-sizing: border-box;\\